const KK = ['tammi', 'helmi', 'maalis', 'huhti', 'touko', 'kesä', 'heinä', 'elo', 'syys', 'loka', 'marras', 'joulu'];
const KKL = ['tam', 'hel', 'maa', 'huh', 'tou', 'kes', 'hei', 'elo', 'syy', 'lok', 'mar', 'jou'];
const ST = {
  uusi: 'Uusi',
  tarjous_lahetetty: 'Tarjous lähetetty',
  tilaus_vastaanotettu: 'Tilaus vastaanotettu',
  suunnittelussa: 'Suunnittelussa',
  tuotannossa: 'Tuotannossa',
  odottaa_asennusta: 'Odottaa asennusta'
};
const ST_JARJ = ['uusi', 'tarjous_lahetetty', 'tilaus_vastaanotettu', 'suunnittelussa', 'tuotannossa', 'odottaa_asennusta'];
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;'
})[c]);
const nf = (v, d = 0) => v == null || isNaN(v) ? '–' : Number(v).toLocaleString('fi-FI', {
  minimumFractionDigits: d,
  maximumFractionDigits: d
});
const eur = v => nf(v) + ' €';
const pvm = s => {
  const p = String(s).slice(0, 10).split('-');
  return +p[2] + '.' + +p[1] + '.';
};
const pvmV = s => pvm(s) + String(s).slice(0, 4);
const mi = k => +k.slice(5, 7) - 1;
const sum = (a, f) => a.reduce((s, x) => s + (Number(f(x)) || 0), 0);
const painotettu = (a, v, n) => {
  const N = sum(a, x => x[n]);
  return N ? sum(a, x => (x[v] || 0) * (x[n] || 0)) / N : null;
};
let jakso = 'kk',
  tab = 'asiakas';
try {
  jakso = localStorage.getItem('kp_tilastot_jakso') || jakso;
  tab = localStorage.getItem('kp_tilastot_tab') || tab;
} catch (e) {}
function jaksoNimi(a) {
  if (!a.length) return '–';
  const f = a[0].kk,
    l = a[a.length - 1].kk;
  if (a.length === 1) return KK[mi(f)] + 'kuu';
  if (f.slice(0, 4) !== l.slice(0, 4)) return KKL[mi(f)] + ' ' + f.slice(2, 4) + ' – ' + KKL[mi(l)] + ' ' + l.slice(2, 4);
  return KK[mi(f)] + '–' + KK[mi(l)] + 'kuu';
}
function jaksot(D) {
  const n = {
    kk: 1,
    '3kk': 3,
    '12kk': 12
  }[jakso] || 1;
  const all = D.kk,
    fiv = (D.fivaldi_paivitetty || '').slice(0, 7);
  const myy = all.filter(x => x.kk < fiv);
  return {
    n,
    cur: all.slice(-n),
    prev: all.slice(-2 * n, -n),
    mCur: myy.slice(-n),
    mPrev: myy.slice(-2 * n, -n),
    fiv
  };
}
function delta(cur, prev, {
  hyvaAlas = false,
  neutraali = false,
  rel = false,
  pp = false,
  d = 0
} = {}) {
  if (cur == null || prev == null || isNaN(cur) || isNaN(prev) || rel && !prev) return '<span class="dl nb">ei vertailua</span>';
  let e = cur - prev;
  if (rel) e = e / prev * 100;
  if (Math.abs(e) < 0.05) return '<span class="dl neu">± 0</span>';
  const yl = e > 0,
    cls = neutraali ? 'neu' : (hyvaAlas ? !yl : yl) ? 'hy' : 'hu';
  return `<span class="dl ${cls}">${yl ? '▲' : '▼'} ${nf(Math.abs(e), d)}${rel ? ' %' : pp ? ' %-yks.' : ''}</span>`;
}
function kateChip(p, R) {
  if (p == null) return '';
  const t = p >= R.hyva ? ['good', '✓', 'Hyvä'] : p >= R.tyyd ? ['warn', '!', 'Tyydyttävä'] : ['crit', '✕', 'Heikko'];
  return `<span class="chip ${t[0]}"><i>${t[1]}</i>${t[2]}</span>`;
}
function ikaChip(pv) {
  if (pv >= 14) return `<span class="chip crit"><i>!</i>${pv} pv</span>`;
  if (pv >= 7) return `<span class="chip serious"><i>!</i>${pv} pv</span>`;
  return `<span class="chip neu">${pv} pv</span>`;
}
function niceMax(v) {
  if (v <= 0) return 1;
  const p = Math.pow(10, Math.floor(Math.log10(v))),
    m = v / p;
  const s = [1, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10].find(x => m <= x);
  return s * p;
}
function tikit(M) {
  const p = Math.pow(10, Math.floor(Math.log10(M))),
    m = Math.round(M / p * 10) / 10;
  return {
    1: 4,
    1.5: 3,
    2: 4,
    2.5: 5,
    3: 3,
    4: 4,
    5: 5,
    6: 3,
    8: 4,
    10: 5
  }[m] || 4;
}
function barPath(x, y, w, h, r) {
  r = Math.min(r, w / 2, h);
  return `M${x},${y + h}V${y + r}Q${x},${y} ${x + r},${y}H${x + w - r}Q${x + w},${y} ${x + w},${y + r}V${y + h}Z`;
}
const tipA = html => `data-tip="${esc(html)}"`;

/* Pystypylväät. rows: [{l, vals:[{v,c,tip,miss}]}] */
function vBars(rows, {
  h = 190,
  W = 620,
  fmtY = nf,
  ticks = null,
  max = null
} = {}) {
  const pL = 46,
    pR = 6,
    pT = 12,
    pB = 24,
    ih = h - pT - pB,
    iw = W - pL - pR,
    cw = iw / rows.length;
  const M = max || niceMax(Math.max(0, ...rows.flatMap(r => r.vals.map(v => v.v || 0))));
  if (!ticks) ticks = tikit(M);
  const k = rows[0] ? rows[0].vals.length : 1,
    bw = Math.min(24, (cw * 0.62 - (k - 1) * 2) / k);
  let s = `<defs><pattern id="hatch" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="6" stroke="#C9CDD2" stroke-width="2"/></pattern></defs>`;
  for (let i = 0; i <= ticks; i++) {
    const y = pT + ih - ih * i / ticks;
    s += `<line class="gl" x1="${pL}" x2="${W - pR}" y1="${y}" y2="${y}"/><text class="ax" x="${pL - 8}" y="${y + 4}" text-anchor="end">${fmtY(M * i / ticks)}</text>`;
  }
  rows.forEach((r, i) => {
    const cx = pL + cw * (i + .5),
      gx = cx - (k * bw + (k - 1) * 2) / 2;
    s += `<g class="hit" ${tipA(r.tip || '')}><rect x="${pL + cw * i}" y="${pT}" width="${cw}" height="${ih}" fill="transparent"/>`;
    r.vals.forEach((v, j) => {
      const x = gx + j * (bw + 2);
      if (v.miss) {
        const mh = Math.min(ih * .18, 26);
        s += `<rect x="${x}" y="${pT + ih - mh}" width="${bw}" height="${mh}" rx="3" fill="url(#hatch)" stroke="#C9CDD2"/>`;
      } else if (v.v > 0) {
        const bh = Math.max(2, ih * v.v / M);
        s += `<path class="bar" d="${barPath(x, pT + ih - bh, bw, bh, 4)}" fill="${v.c || 'var(--blue)'}"/>`;
      }
    });
    s += `</g><text class="ax" x="${cx}" y="${h - 6}" text-anchor="middle">${esc(r.l)}</text>`;
  });
  s += `<line class="base" x1="${pL}" x2="${W - pR}" y1="${pT + ih}" y2="${pT + ih}"/>`;
  return `<svg class="ch" viewBox="0 0 ${W} ${h}">${s}</svg>`;
}
/* Viivakaavio. pts:[{l,tip,...}], series:[{k,c}] */
function lineCh(pts, series, {
  h = 200,
  W = 760,
  fmtY = nf,
  ticks = null,
  every = 7
} = {}) {
  const pL = 40,
    pR = 10,
    pT = 12,
    pB = 24,
    ih = h - pT - pB,
    iw = W - pL - pR;
  const M = niceMax(Math.max(1, ...pts.flatMap(p => series.map(s => p[s.k] || 0))));
  if (!ticks) ticks = tikit(M);
  const X = i => pL + (pts.length < 2 ? iw / 2 : iw * i / (pts.length - 1)),
    Y = v => pT + ih - ih * v / M;
  let s = '';
  for (let i = 0; i <= ticks; i++) {
    const y = pT + ih - ih * i / ticks;
    s += `<line class="gl" x1="${pL}" x2="${W - pR}" y1="${y}" y2="${y}"/><text class="ax" x="${pL - 8}" y="${y + 4}" text-anchor="end">${fmtY(M * i / ticks)}</text>`;
  }
  s += `<line class="base" x1="${pL}" x2="${W - pR}" y1="${pT + ih}" y2="${pT + ih}"/>`;
  series.forEach(se => {
    s += `<path d="${pts.map((p, i) => (i ? 'L' : 'M') + X(i).toFixed(1) + ',' + Y(p[se.k] || 0).toFixed(1)).join('')}" fill="none" stroke="${se.c}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>`;
  });
  const last = pts.length - 1;
  series.forEach(se => {
    s += `<circle cx="${X(last)}" cy="${Y(pts[last][se.k] || 0)}" r="4" fill="${se.c}" stroke="#fff" stroke-width="2"/>`;
  });
  const cw = pts.length > 1 ? iw / (pts.length - 1) : iw;
  pts.forEach((p, i) => {
    s += `<g class="col" ${tipA(p.tip || '')}><rect x="${X(i) - cw / 2}" y="${pT}" width="${cw}" height="${ih}" fill="transparent"/><line class="hl" x1="${X(i)}" x2="${X(i)}" y1="${pT}" y2="${pT + ih}" stroke="#9AA1AA" stroke-width="1"/>`;
    series.forEach(se => {
      s += `<circle class="hl" cx="${X(i)}" cy="${Y(p[se.k] || 0)}" r="4" fill="${se.c}" stroke="#fff" stroke-width="2"/>`;
    });
    s += `</g>`;
    if (i % every === 0 || i === last) s += `<text class="ax" x="${X(i)}" y="${h - 6}" text-anchor="${i === last ? 'end' : i === 0 ? 'start' : 'middle'}">${esc(p.l)}</text>`;
  });
  return `<svg class="ch" viewBox="0 0 ${W} ${h}">${s}</svg>`;
}
function spark(vals, c = 'var(--blue)') {
  const W = 160,
    H = 26,
    M = Math.max(1, ...vals),
    m = Math.min(...vals),
    r = M - m || 1;
  const X = i => 2 + (W - 4) * i / (vals.length - 1),
    Y = v => H - 3 - (H - 6) * (v - m) / r;
  return `<svg class="spark" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><path d="${vals.map((v, i) => (i ? 'L' : 'M') + X(i).toFixed(1) + ',' + Y(v).toFixed(1)).join('')}" fill="none" stroke="${c}" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linejoin="round"/></svg>`;
}
function hBars(rows, {
  fmt = nf,
  c = 'var(--blue)'
} = {}) {
  const M = Math.max(1, ...rows.map(r => r.v));
  return '<div class="hb">' + rows.map(r => `<div class="hbr" ${tipA(r.tip || '')}><div class="hbl">${esc(r.l)}</div><div class="hbt"><div class="hbf" style="width:${(r.v / M * 100).toFixed(1)}%;background:${r.c || c}"></div></div><div class="hbv">${fmt(r.v)}</div></div>`).join('') + '</div>';
}
function vk(s) {
  const d = new Date(s + 'T00:00:00Z');
  const day = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - day);
  const y0 = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil(((d - y0) / 864e5 + 1) / 7);
}

/* ---------- Sivu ---------- */
function render(D) {
  const J = jaksot(D),
    R = D.rajat,
    T = D.trendi,
    tN = T[T.length - 1],
    t7 = T[Math.max(0, T.length - 8)];
  const inCur = k => J.cur.some(x => x.kk === k);

  // KPI-luvut
  const myyC = sum(J.mCur, x => x.myynti),
    myyP = J.mPrev.length === J.n ? sum(J.mPrev, x => x.myynti) : null;
  const kH = sum(J.cur, x => x.kate_hinta),
    kK = sum(J.cur, x => x.kate_kust),
    kN = sum(J.cur, x => x.kate_n);
  const kP = kH > 0 ? (kH - kK) / kH * 100 : null;
  const pH = sum(J.prev, x => x.kate_hinta),
    pK = sum(J.prev, x => x.kate_kust),
    pN = sum(J.prev, x => x.kate_n);
  const kPp = pN >= 3 && pH > 0 ? (pH - pK) / pH * 100 : null;
  const tilC = sum(J.cur, x => x.tilauksia),
    lasC = sum(J.cur, x => x.laskurilla),
    tilP = sum(J.prev, x => x.tilauksia),
    lasP = sum(J.prev, x => x.laskurilla);
  const lskC = tilC ? lasC / tilC * 100 : null,
    lskP = tilP ? lasP / tilP * 100 : null;
  const tile = (label, val, ts, extra = '', hint = '') => `<div class="tile"><div class="tl"><span>${label}</span><small>${hint}</small></div><div class="tv">${val}</div>${extra}<div class="ts">${ts}</div></div>`;
  const kpis = [tile('Avoimet työt', nf(D.nyt.avoimia), `${delta(tN.avoimia, t7.avoimia, {
    neutraali: true
  })}<span>vs. viikko sitten</span>`, spark(T.map(x => x.avoimia)), 'nyt'), tile('Odottaa meitä', nf(D.nyt.odottaa_meita), `${delta(tN.odottaa, t7.odottaa, {
    hyvaAlas: true
  })}<span>vs. viikko sitten</span>`, spark(T.map(x => x.odottaa)), 'nyt'), tile('Myöhässä', nf(D.nyt.myohassa) + (D.nyt.myohassa > 0 ? ' <span class="chip crit"><i>!</i>Myöhässä</span>' : ' <span class="chip good"><i>✓</i>Ei myöhässä</span>'), `${delta(tN.myohassa, t7.myohassa, {
    hyvaAlas: true
  })}<span>vs. viikko sitten</span>`, spark(T.map(x => x.myohassa)), 'nyt'), tile('Myynti', eur(myyC), `${delta(myyC, myyP, {
    rel: true
  })}<span>vs. edellinen jakso</span>`, '', esc(jaksoNimi(J.mCur))), tile('Kate', kP == null ? '–' : nf(kP, 1) + ' %' + ' ' + kateChip(kP, R), `${delta(kP, kPp, {
    pp: true,
    d: 1
  })}<span>${kN} laskutettua työtä</span>`, '', esc(jaksoNimi(J.cur))), tile('Laskurilla tehty', lskC == null ? '–' : nf(lskC, 0) + ' %', `${delta(lskC, lskP, {
    pp: true
  })}<span>${lasC} / ${tilC} tilausta</span>`, '', esc(jaksoNimi(J.cur)))].join('');
  const tabs = [['asiakas', 'Asiakaspalvelu', D.vastaamatta.length], ['myynti', 'Myynti & kate', null], ['tuotanto', 'Tuotanto', D.myohassa.length], ['laatu', 'Datan laatu', null]];
  document.getElementById('app').innerHTML = `
  <header>
    <div><h1>Tilastot</h1><div class="sub">Päivitetty ${pvmV(D.paiva)} · myynti Fivaldista, tuotu ${pvmV(D.fivaldi_paivitetty)}</div></div>
    <div class="seg" id="seg">${[['kk', 'Tämä kuukausi'], ['3kk', '3 kk'], ['12kk', '12 kk']].map(([k, l]) => `<button data-j="${k}" class="${jakso === k ? 'on' : ''}">${l}</button>`).join('')}</div>
  </header>
  <div class="kpis">${kpis}</div>
  <div class="tabs" id="tabs">${tabs.map(([k, l, n]) => `<button data-t="${k}" class="${tab === k ? 'on' : ''}">${l}${n ? `<span class="n">${n}</span>` : ''}</button>`).join('')}</div>
  <div id="sisalto">${({
    asiakas: tAsiakas,
    myynti: tMyynti,
    tuotanto: tTuotanto,
    laatu: tLaatu
  }[tab] || tAsiakas)(D, J, inCur)}</div>
  <details><summary>Miten luvut lasketaan?</summary><ul>
    <li><b>Avoimet työt</b>: arkistoimattomat työt, joiden tila ei ole valmis, toimitettu, laskutettu tai hylätty.</li>
    <li><b>Odottaa meitä</b>: avoimet työt, joiden viimeisin viesti on asiakkaalta tullut.</li>
    <li><b>Myöhässä</b>: valmistumispäivä on mennyt eikä työ ole valmis, toimitettu tai laskutettu.</li>
    <li><b>Myynti</b>: Fivaldin laskut (veroton) laskun päivän mukaan. Kuluva kuukausi näkyy vasta seuraavan tuonnin jälkeen, joten ”tämä kuukausi” näyttää viimeisimmän tuodun kuukauden.</li>
    <li><b>Kate</b>: työkortille laskutushetkellä tallennettu lopullinen kate (hinta − toteutunut omakustannus), laskutuskuukauden mukaan.</li>
    <li><b>Tilauksista laskurilla</b>: jakson tilauksista ne, joille on tehty hintalaskuri.</li>
    <li><b>Vastausaika</b>: tarjouspyynnön saapumisesta ensimmäiseen lähtevään viestiin. <b>Läpimenoaika</b>: arkipäivät tilauksen vastaanotosta valmiiksi tai toimitetuksi.</li>
    <li>Vertailu: kuukausiluvut verrataan edelliseen samanpituiseen jaksoon, ”nyt”-luvut viikon takaiseen tilanteeseen.</li>
  </ul></details>`;
  document.getElementById('seg').onclick = e => {
    const b = e.target.closest('button');
    if (!b) return;
    jakso = b.dataset.j;
    try {
      localStorage.setItem('kp_tilastot_jakso', jakso);
    } catch (x) {}
    render(D);
  };
  document.getElementById('tabs').onclick = e => {
    const b = e.target.closest('button');
    if (!b) return;
    tab = b.dataset.t;
    try {
      localStorage.setItem('kp_tilastot_tab', tab);
    } catch (x) {}
    render(D);
