    kH = sum(J.cur, x => x.kate_hinta),
    kK = sum(J.cur, x => x.kate_kust),
    kP = kH > 0 ? (kH - kK) / kH * 100 : null;
  const kateKk = D.kk.filter(x => x.kate_n > 0);
  const kkD = D.kk.filter(x => x.tarjouspyyntoja > 0 || x.tilauksia > 0);
  const ttRows = kkD.map(x => ({
    l: KKL[mi(x.kk)],
