  const vRows = D.vastuu.map(x => ({
    l: x.v,
    v: x.n,
    c: x.v === 'Ei vastuuhenkilöä' ? '#C9CDD2' : 'var(--blue)',
    tip: `<b>${esc(x.v)}</b><br>${x.n} avointa työtä`
