  return `<div class="g">
    <div class="card s6"><h3>Tilauksista laskurilla</h3><div class="cap">Osuus kuukauden tilauksista, joille on tehty hintalaskuri</div>
      ${vBars(lRows, {
    h: 180,
    W: 520,
    max: 100,
    fmtY: v => nf(v) + ' %'
  })}
      <div class="note">Postilaatikkokilvet tulevat laskuriin automaattisesti 16.10. alkaen, mikä nostaa osuutta.</div></div>
    <div class="card s6"><h3>Avoimista töistä puuttuu</h3><div class="cap">${N} avointa työtä · puuttuva tieto heikentää kuormitus- ja katelukuja</div>
      ${hBars(puute.map(([l, v]) => ({
    l,
    v,
    c: 'var(--blue)',
    tip: `<b>${l}</b><br>${v} / ${N} avointa työtä (${nf(v / N * 100, 0)} %)`
  })), {
    fmt: v => `${v} · ${nf(v / N * 100, 0)} %`
  })}</div>
  </div>`;
}
const tip = document.getElementById('tip');
document.addEventListener('mousemove', e => {
  const el = e.target.closest && e.target.closest('[data-tip]');
  if (!el || !el.dataset.tip) {
    tip.style.opacity = 0;
    return;
  }
  tip.innerHTML = el.dataset.tip;
  tip.style.opacity = 1;
  const r = tip.getBoundingClientRect();
  let x = e.clientX + 14,
    y = e.clientY + 14;
  if (x + r.width > innerWidth - 8) x = e.clientX - r.width - 14;
  if (y + r.height > innerHeight - 8) y = e.clientY - r.height - 14;
  tip.style.left = x + 'px';
  tip.style.top = y + 'px';
});
function aja() {
  const m = appsmith.model || {};
  let D = m.data;
  if (typeof D === 'string') {
    try {
      D = JSON.parse(D);
    } catch (e) {
      D = null;
    }
  }
  if (D && D.kk) {
    render(D);
  } else {
    document.getElementById('app').innerHTML = '<div class="empty" style="padding:24px">Ladataan tilastoja…</div>';
  }
}
appsmith.onReady(aja);
appsmith.onModelChange(aja);

