:root{
  --bg:#F5F6F8; --card:#fff; --line:#E3E5E8; --grid:#EEF0F2;
  --ink:#1F2328; --ink2:#5B636E; --muted:#8A929C;
  --blue:#2a78d6; --blue-l:#b9d3f3; --aqua:#1baf7a; --brand:#B4232A;
  --good:#0ca30c; --warn:#fab219; --serious:#ec835a; --crit:#d03b3b;
}
*{box-sizing:border-box}
body{margin:0;background:transparent;color:var(--ink);font:14px/1.45 Inter,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased}
.wrap{max-width:1280px;margin:0 auto;padding:4px 2px 24px}
header{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:12px;margin-bottom:16px}
h1{font-size:22px;font-weight:650;margin:0}
.sub{color:var(--ink2);font-size:13px;margin-top:2px}
.seg{display:inline-flex;background:#fff;border:1px solid var(--line);border-radius:10px;padding:3px;gap:2px}
.seg button{border:0;background:transparent;font:inherit;font-size:13px;color:var(--ink2);padding:6px 12px;border-radius:7px;cursor:pointer}
.seg button.on{background:#EAF2FC;color:var(--ink);font-weight:600}
.kpis{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin-bottom:20px}
.card,.tile{background:var(--card);border:1px solid var(--line);border-radius:12px}
.tile{padding:12px 14px 10px;display:flex;flex-direction:column;gap:2px;min-height:122px}
.tl{font-size:13px;color:var(--ink2);display:flex;justify-content:space-between;gap:6px}
.tl small{color:var(--muted);font-size:12px}
.tv{font-size:25px;font-weight:650;letter-spacing:-.01em;display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.ts{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--muted);flex-wrap:wrap;margin-top:auto}
.spark{width:100%;height:26px;display:block;margin-top:4px}
.dl{font-size:12.5px;font-weight:600;white-space:nowrap}
.dl.hy{color:#0a7f0a}.dl.hu{color:#b42f2f}.dl.neu,.dl.nb{color:var(--ink2);font-weight:500}
.chip{display:inline-flex;align-items:center;gap:5px;font-size:12px;font-weight:600;padding:2px 8px 2px 4px;border-radius:999px;color:var(--ink);white-space:nowrap}
.chip i{font-style:normal;width:16px;height:16px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;color:#fff;font-size:10px;font-weight:700}
.chip.good{background:#e6f5e6}.chip.good i{background:var(--good)}
.chip.warn{background:#fff4d6}.chip.warn i{background:var(--warn);color:#1F2328}
.chip.serious{background:#fdeee7}.chip.serious i{background:var(--serious)}
.chip.crit{background:#fbe7e7}.chip.crit i{background:var(--crit)}
.chip.neu{background:#F0F2F4;color:var(--ink2);padding-left:8px}
.tabs{display:flex;gap:4px;border-bottom:1px solid var(--line);margin-bottom:16px;overflow-x:auto}
.tabs button{border:0;background:transparent;font:inherit;font-size:14px;color:var(--ink2);padding:10px 14px;cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-1px;white-space:nowrap}
.tabs button.on{color:var(--ink);font-weight:600;border-bottom-color:var(--brand)}
.tabs .n{display:inline-block;min-width:20px;padding:0 6px;margin-left:6px;border-radius:999px;background:#F0F2F4;color:var(--ink2);font-size:12px;font-weight:600}
.g{display:grid;grid-template-columns:repeat(12,1fr);gap:12px}
.s4{grid-column:span 4}.s5{grid-column:span 5}.s6{grid-column:span 6}.s7{grid-column:span 7}.s8{grid-column:span 8}.s12{grid-column:span 12}
@media (max-width:1000px){.kpis{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (max-width:900px){.s4,.s5,.s6,.s7,.s8{grid-column:span 12}}
.card{padding:16px 18px}
.card h3{margin:0;font-size:15px;font-weight:600}
.cap{color:var(--muted);font-size:12.5px;margin:2px 0 12px}
.big{font-size:30px;font-weight:650;display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:4px 0 2px}
.big small{font-size:13px;font-weight:500;color:var(--ink2)}
.legend{display:flex;gap:14px;font-size:12.5px;color:var(--ink2);margin:-4px 0 6px;flex-wrap:wrap}
.legend span{display:inline-flex;align-items:center;gap:6px}
.legend b{width:10px;height:10px;border-radius:3px;display:inline-block}
svg.ch{width:100%;height:auto;display:block;overflow:visible}
.gl{stroke:var(--grid);stroke-width:1}
.base{stroke:#C9CDD2;stroke-width:1}
.ax{fill:var(--muted);font-size:11px}
.axv{fill:var(--ink2);font-size:11px;font-weight:600}
.hit:hover .bar{filter:brightness(.92)}
.col .hl{opacity:0}.col:hover .hl{opacity:1}
.hb{display:flex;flex-direction:column;gap:8px}
.hbr{display:grid;grid-template-columns:minmax(110px,190px) 1fr 70px;align-items:center;gap:10px;font-size:13px}
.hbl{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ink)}
.hbt{height:12px;background:#F2F4F6;border-radius:4px;overflow:hidden}
.hbf{height:100%;border-radius:0 4px 4px 0}
.hbv{text-align:right;color:var(--ink2);font-variant-numeric:tabular-nums}
.list{display:flex;flex-direction:column}
.li{display:grid;grid-template-columns:110px 1fr auto;gap:10px;align-items:center;padding:8px 0;border-top:1px solid var(--grid);font-size:13px}
.li:first-child{border-top:0}
.li .tp{color:var(--ink2);font-variant-numeric:tabular-nums}
.li .as{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.li .as small{color:var(--muted);margin-left:6px}
.empty{color:var(--muted);font-size:13px;padding:8px 0}
.kv{display:flex;justify-content:space-between;padding:6px 0;border-top:1px solid var(--grid);font-size:13px}
.kv:first-of-type{border-top:0}
.kv span:last-child{font-variant-numeric:tabular-nums;color:var(--ink2)}
.note{font-size:12.5px;color:var(--ink2);background:#F7F8FA;border:1px solid var(--line);border-radius:8px;padding:8px 10px;margin-top:10px}
details{margin-top:20px;font-size:13px;color:var(--ink2)}
details summary{cursor:pointer;color:var(--ink)}
details ul{margin:8px 0 0;padding-left:18px}
#tip{position:fixed;pointer-events:none;opacity:0;transition:opacity .08s;background:#1F2328;color:#fff;font-size:12.5px;line-height:1.4;padding:7px 10px;border-radius:8px;box-shadow:0 4px 14px rgba(0,0,0,.18);z-index:10;max-width:260px}
#tip b{font-weight:600}

