/* Pystypylväät. rows: [{l, vals:[{v,c,tip,miss}]}] */
function vBars(rows,{h=190,W=620,fmtY=nf,ticks=null,max=null}={}){
  const pL=46,pR=6,pT=12,pB=24,ih=h-pT-pB,iw=W-pL-pR,cw=iw/rows.length;
