    <div class="card s8"><h3>Avoimet ja vastaustamme odottavat työt</h3><div class="cap">Päivittäinen tilanne, viimeiset 4 viikkoa</div>
      <div class="legend"><span><b style="background:var(--blue)"></b>Avoimet työt</span><span><b style="background:var(--aqua)"></b>Odottaa meitä</span></div>
      ${lineCh(pts,[{k:'avoimia',c:'var(--blue)'},{k:'odottaa',c:'var(--aqua)'}])}</div>
    <div class="card s4"><h3>Vastausaika tarjouspyyntöihin</h3><div class="cap">${esc(jaksoNimi(J.cur))} · keskiarvo</div>
      <div class="big">${va==null?'–':nf(va,1)+' pv'} <small>${vaN} tarjouspyyntöä</small></div>
      ${vBars(vaRows,{h:150,W:320,fmtY:v=>nf(v,1)})}
      <div class="note">Seuranta alkoi syyskuussa 2026, joten historia kertyy vasta.</div></div>
    <div class="card s12"><h3>Vastaamatta olevat tarjouspyynnöt</h3><div class="cap">${D.vastaamatta.length} kpl · vanhimmat ensin · punainen yli 14 pv, oranssi yli 7 pv</div>
      <div class="list">${D.vastaamatta.map(x=>`<div class="li"><span class="tp">${esc(x.tp)}</span><span class="as">${esc(x.asiakas||'(asiakas puuttuu)')}</span>${ikaChip(x.pv)}</div>`).join('')||'<div class="empty">Ei vastaamattomia.</div>'}</div></div>
  </div>`;
}

function tMyynti(D,J,inCur){
  const fiv=J.fiv;
  const myyRows=D.kk.map(x=>{const miss=x.kk>=fiv;return {l:KKL[mi(x.kk)],vals:[{v:x.myynti,miss,c:J.mCur.some(m=>m.kk===x.kk)?'var(--blue)':'var(--blue-l)'}],
    tip:miss?`<b>${KK[mi(x.kk)]}kuu ${x.kk.slice(0,4)}</b><br>Ei vielä tuotu Fivaldista`:`<b>${KK[mi(x.kk)]}kuu ${x.kk.slice(0,4)}</b><br>Myynti ${eur(x.myynti)}<br>${x.laskuja} laskua`};});
  const yht=sum(D.kk.filter(x=>x.kk<fiv),x=>x.myynti);
  const kN=sum(J.cur,x=>x.kate_n),kH=sum(J.cur,x=>x.kate_hinta),kK=sum(J.cur,x=>x.kate_kust),kP=kH>0?(kH-kK)/kH*100:null;
  const kateKk=D.kk.filter(x=>x.kate_n>0);
  const kkD=D.kk.filter(x=>x.tarjouspyyntoja>0||x.tilauksia>0);
  const ttRows=kkD.map(x=>({l:KKL[mi(x.kk)],vals:[{v:x.tarjouspyyntoja,c:'var(--blue)'},{v:x.tilauksia,c:'var(--aqua)'}],tip:`<b>${KK[mi(x.kk)]}kuu</b><br>Tarjouspyyntöjä ${x.tarjouspyyntoja}<br>Tilauksia ${x.tilauksia}`}));
  const tk=D.tyon_koko, tkV=tk[tk.length-1];
  const tkPts=tk.map(x=>({l:KKL[mi(x.kk)],m:x.mediaani,tip:`<b>${KK[mi(x.kk)]}kuu ${x.kk.slice(0,4)}</b><br>Mediaani ${eur(x.mediaani)}<br>Alle ${x.raja} €: ${nf(x.pienia_pct,1)} %`}));
  return `<div class="g">
    <div class="card s8"><h3>Myynti kuukausittain</h3><div class="cap">Veroton laskutus Fivaldista · 12 kk yhteensä ${eur(yht)} · tummempi = valittu jakso</div>
      ${vBars(myyRows,{fmtY:v=>v>=1000?nf(v/1000)+' t€':nf(v)})}</div>
    <div class="card s4"><h3>Kate</h3><div class="cap">${esc(jaksoNimi(J.cur))} · laskutetut työt</div>
      <div class="big">${kP==null?'–':nf(kP,1)+' %'} ${kateChip(kP,D.rajat)}</div>
      <div class="kv"><span>Laskutettuja töitä</span><span>${kN}</span></div>
      <div class="kv"><span>Laskutettu hinta</span><span>${eur(kH)}</span></div>
      <div class="kv"><span>Toteutunut omakustannus</span><span>${eur(kK)}</span></div>
      <div class="kv"><span>Kate €</span><span>${eur(kH-kK)}</span></div>
      <div class="note">Rajat samat kuin laskurissa: hyvä ≥ ${D.rajat.hyva} %, tyydyttävä ${D.rajat.tyyd}–${D.rajat.hyva} %. ${kateKk.length<3?'Katetta on tallennettu laskutushetkellä vasta lokakuusta alkaen.':''}</div></div>
    <div class="card s4"><h3>Tarjouspyynnöt ja tilaukset</h3><div class="cap">Saapuneet kuukausittain</div>
      <div class="legend"><span><b style="background:var(--blue)"></b>Tarjouspyynnöt</span><span><b style="background:var(--aqua)"></b>Tilaukset</span></div>
      ${vBars(ttRows,{h:170,W:320})}</div>
    <div class="card s4"><h3>Suurimmat asiakkaat</h3><div class="cap">Myynti 12 kk</div>
      ${hBars(D.asiakkaat.map(x=>({l:x.a,v:x.myynti,tip:`<b>${esc(x.a)}</b><br>${eur(x.myynti)} · ${x.n} laskua`})),{fmt:v=>nf(v/1000,1)+' t€'})}</div>
    <div class="card s4"><h3>Työn koko</h3><div class="cap">Laskun mediaani kuukausittain</div>
      <div class="big">${eur(tkV.mediaani)} <small>${nf(tkV.pienia_pct,0)} % alle ${tkV.raja} €</small></div>
      ${lineCh(tkPts,[{k:'m',c:'var(--blue)'}],{h:130,W:320,every:3,fmtY:v=>nf(v)})}</div>
  </div>`;
}

function tTuotanto(D,J,inCur){
  const lp=painotettu(J.cur,'lapi_pv','lapi_n'),lpN=sum(J.cur,x=>x.lapi_n);
  const kkD=D.kk.filter(x=>x.lapi_n>0);
  const lpRows=kkD.map(x=>({l:KKL[mi(x.kk)],vals:[{v:x.lapi_pv,c:inCur(x.kk)?'var(--blue)':'var(--blue-l)'}],tip:`<b>${KK[mi(x.kk)]}kuu</b><br>Läpimeno ${nf(x.lapi_pv,1)} arkipv<br>${x.lapi_n} työtä`}));
  const vkRows=D.viikot.map((x,i)=>({l:'vk '+vk(x.alku),vals:[{v:x.n,c:'var(--blue)'}],tip:`<b>Viikko ${vk(x.alku)}</b> (alkaa ${pvm(x.alku)})<br>Valmistuu ${x.n} työtä${i===0?'<br>Kuluva viikko':''}`}));
  const stMap=Object.fromEntries(D.status.map(x=>[x.s,x.n]));
  const stRows=ST_JARJ.filter(s=>stMap[s]).map(s=>({l:ST[s]||s,v:stMap[s],tip:`<b>${ST[s]||s}</b><br>${stMap[s]} työtä`}));
  const vRows=D.vastuu.map(x=>({l:x.v,v:x.n,c:x.v==='Ei vastuuhenkilöä'?'#C9CDD2':'var(--blue)',tip:`<b>${esc(x.v)}</b><br>${x.n} avointa työtä`}));
  return `<div class="g">
    <div class="card s6"><h3>Myöhässä olevat työt</h3><div class="cap">${D.myohassa.length} kpl · eniten myöhässä ensin</div>
      <div class="list">${D.myohassa.map(x=>`<div class="li"><span class="tp">${esc(x.tp)}</span><span class="as">${esc(x.asiakas)}<small>${esc(x.vastuu||'')} · piti valmistua ${pvm(x.pvm)}</small></span><span class="chip crit"><i>!</i>${x.pv} pv</span></div>`).join('')||'<div class="empty">Ei myöhässä olevia töitä.</div>'}</div></div>
    <div class="card s6"><h3>Valmistuvat viikoittain</h3><div class="cap">Avoimet työt valmistumispäivän mukaan · ${D.nyt.ilman_valmistumispaivaa} työltä puuttuu päivä</div>
      ${vBars(vkRows,{h:170,W:520})}</div>
    <div class="card s4"><h3>Työt vaiheittain</h3><div class="cap">Avoimet työt tilan mukaan</div>${hBars(stRows)}</div>
    <div class="card s4"><h3>Vastuuhenkilöt</h3><div class="cap">Avoimet työt</div>${hBars(vRows)}</div>
    <div class="card s4"><h3>Läpimenoaika</h3><div class="cap">${esc(jaksoNimi(J.cur))} · tilauksesta valmiiksi</div>
      <div class="big">${lp==null?'–':nf(lp,1)+' arkipv'} <small>${lpN} työtä</small></div>
      ${vBars(lpRows,{h:120,W:320,fmtY:v=>nf(v,1)})}</div>
    <div class="card s12"><h3>Tulevat asennukset</h3><div class="cap">${D.asennukset.length} kpl</div>
      <div class="list">${D.asennukset.map(x=>`<div class="li"><span class="tp">${esc(x.tp)}</span><span class="as">${esc(x.asiakas)}<small>${esc(x.vastuu||'')}</small></span><span class="chip neu">${pvmV(x.pvm)}</span></div>`).join('')||'<div class="empty">Ei tulevia asennuksia.</div>'}</div></div>
  </div>`;
}

function tLaatu(D,J,inCur){
  const kkD=D.kk.filter(x=>x.tilauksia>0);
  const lRows=kkD.map(x=>{const p=x.laskurilla/x.tilauksia*100;return {l:KKL[mi(x.kk)],vals:[{v:p,c:inCur(x.kk)?'var(--blue)':'var(--blue-l)'}],tip:`<b>${KK[mi(x.kk)]}kuu</b><br>${nf(p,0)} % laskurilla<br>${x.laskurilla} / ${x.tilauksia} tilausta`};});
  const N=D.nyt.avoimia;
  const puute=[['Valmistumispäivä puuttuu',D.nyt.ilman_valmistumispaivaa],['Hinta puuttuu',D.nyt.ilman_hintaa],['Vastuuhenkilö puuttuu',D.nyt.ilman_vastuuhenkiloa]];
  return `<div class="g">
    <div class="card s6"><h3>Tilauksista laskurilla</h3><div class="cap">Osuus kuukauden tilauksista, joille on tehty hintalaskuri</div>
      ${vBars(lRows,{h:180,W:520,max:100,fmtY:v=>nf(v)+' %'})}
      <div class="note">Postilaatikkokilvet tulevat laskuriin automaattisesti 16.10. alkaen, mikä nostaa osuutta.</div></div>
    <div class="card s6"><h3>Avoimista töistä puuttuu</h3><div class="cap">${N} avointa työtä · puuttuva tieto heikentää kuormitus- ja katelukuja</div>
      ${hBars(puute.map(([l,v])=>({l,v,c:'var(--blue)',tip:`<b>${l}</b><br>${v} / ${N} avointa työtä (${nf(v/N*100,0)} %)`})),{fmt:v=>`${v} · ${nf(v/N*100,0)} %`})}</div>
  </div>`;
}

const tip=document.getElementById('tip');
document.addEventListener('mousemove',e=>{
  const el=e.target.closest&&e.target.closest('[data-tip]');
  if(!el||!el.dataset.tip){tip.style.opacity=0;return;}
  tip.innerHTML=el.dataset.tip;tip.style.opacity=1;
  const r=tip.getBoundingClientRect();let x=e.clientX+14,y=e.clientY+14;
  if(x+r.width>innerWidth-8)x=e.clientX-r.width-14;if(y+r.height>innerHeight-8)y=e.clientY-r.height-14;
  tip.style.left=x+'px';tip.style.top=y+'px';
});
function aja(){const m=appsmith.model||{};let D=m.data;if(typeof D==='string'){try{D=JSON.parse(D);}catch(e){D=null;}}if(D&&D.kk){render(D);}else{document.getElementById('app').innerHTML='<div class="empty" style="padding:24px">Ladataan tilastoja…</div>';}}
appsmith.onReady(aja);
appsmith.onModelChange(aja);
